import {latestPlans,studyMinutes,validateStudyEntries} from './study-domain.mjs';
export function createStudy(ctx){
const {esc,icon,seed,dateLabel,addDays}=ctx;let selected=null,month=null;const state=()=>ctx.state(),sum=()=>ctx.summary(),date=()=>selected||ctx.today();
const topic=id=>seed.problems.find(p=>p.id===id)?.title||seed.roadmap.find(w=>w.systemDesignId===id)?.systemDesign||id;
const label=(s)=>`<span class="eyebrow">${s}</span>`;
function shell(content){const active=ctx.view()==='design'?'design':ctx.view()==='planner'?'planner':'practice';return `<div class="studio"><header class="studio-header"><a href="#practice" class="studio-brand"><span class="studio-mark">${icon('code',21)}</span><b>DSA<span>now</span></b></a><nav aria-label="Main navigation">${[['practice','DSA Sheet'],['design','System Design'],['planner','Daily Planner']].map(([v,t])=>`<a href="#${v}" class="${active===v?'active':''}" ${active===v?'aria-current="page"':''}>${t}${v==='planner'?'<span class="nav-dot"></span>':''}</a>`).join('')}</nav><div class="studio-tools"><span class="save-state" id="save-label">${ctx.storageError()?'Save needs attention':'Saved locally'}</span><a class="icon-button" href="#settings" aria-label="Settings and backups" title="Settings and backups">${icon('settings',21)}</a></div></header><main id="main" tabindex="-1">${ctx.storageError()?`<div class="alert error">${esc(ctx.storageError())}<button class="text-button" data-action="reload">Reload progress</button></div>`:''}${content}<footer class="studio-footer"><span>Made for the work. One session at a time.</span><div><a href="#history">Activity history</a><button data-action="export">Export backup ${icon('download',14)}</button><span>${icon('shield',13)} Browser storage</span></div></footer></main></div>`;}
function groups(rows){if(!rows.length)return `<div class="sheet-empty"><h3>No matching problems.</h3><p>Try another search or reset the filters.</p><button class="btn outline" data-action="reset-filters">Reset filters</button></div>`;const f=ctx.filters(),first=rows.find(p=>!sum().reviews[p.id].everSolved)?.moduleId||rows[0].moduleId;return seed.modules.filter(m=>rows.some(p=>p.moduleId===m.id)).map(m=>{const tasks=rows.filter(p=>p.moduleId===m.id),completed=tasks.filter(p=>sum().reviews[p.id].everSolved).length;return `<details class="sheet-topic" ${m.id===first||f.query||f.module!=='all'||f.status!=='all'?'open':''}><summary><span class="topic-monogram">${m.letter}</span><div><h3>${esc(m.title)}</h3><span>${tasks.length} problems${m.optionalOnly?' · Optional deep dive':''}</span></div><div class="topic-meter"><span>${completed}<small> / ${tasks.length}</small></span><i><b style="width:${completed/tasks.length*100}%"></b></i></div>${icon('chevron',17)}</summary><div class="sheet-columns"><span>PROBLEM</span><span>LEVEL</span><span>PROGRESS</span><span></span></div>${tasks.map((p,i)=>{const r=sum().reviews[p.id];return `<div class="sheet-problem"><button class="solve-marker ${r.everSolved?'solved':''}" data-task="${p.id}" aria-label="Open ${esc(p.title)}">${r.everSolved?icon('check',14):String(i+1).padStart(2,'0')}</button><button class="sheet-problem-title" data-task="${p.id}">${esc(p.title)}<small>${p.id} ${r.nextDueDate?'· Review '+dateLabel(r.nextDueDate):'· '+p.track}</small></button><span class="level level-${p.difficulty.toLowerCase()}">${esc(p.difficulty)}</span><span class="sheet-status ${r.everSolved?'complete':''}">${r.retained?'Retained':r.everSolved?'Solved':r.latest?'Practising':'Not started'}</span><button class="row-arrow" data-task="${p.id}" aria-label="Practise ${esc(p.title)}">${icon('arrow',18)}</button></div>`}).join('')}</details>`;}).join('');}
function sheet(){const s=sum(),f=ctx.filters(),next=s.core.find(p=>!s.reviews[p.id].everSolved),minutes=studyMinutes(state(),ctx.today()),actual=minutes.dsa+minutes.design,target=state().careerProfile.dailyMinutes,pct=Math.round(s.solved/96*100),rows=ctx.filtered();return `<div class="sheet-heading"><div>${label('YOUR JAVA DSA WORKSPACE')}<h1>One problem <span>closer.</span></h1><p>A clear sheet. Consistent practice. Progress that stays with you.</p></div><div class="heading-metrics"><div><b>${s.solved}<small>/96</small></b><span>core solved</span></div><div><b>${s.retained}</b><span>retained</span></div><div><b>${s.streak}<small>d</small></b><span>study streak</span></div></div></div><div class="focus-strip"><section class="next-problem"><div>${label(state().settings.paused?'TAKE YOUR TIME':'PICK UP HERE')}<h2>${state().settings.paused?'Suggestions are paused.':next?esc(next.title):'Make your patterns stick.'}</h2><p>${next?esc(seed.modules.find(m=>m.id===next.moduleId).title)+' · Java · '+next.difficulty:'Your core sheet is complete. Revisit weak patterns.'}</p>${state().settings.paused?'<a class="btn primary" href="#settings">Resume practice</a>':next?`<button class="btn primary" data-task="${next.id}">Let’s solve it ${icon('arrow',17)}</button>`:'<a class="btn primary" href="#reviews">Open revision</a>'}</div><div class="code-art" aria-hidden="true"><div class="code-art-top"><i></i><i></i><i></i><span>Main.java</span></div><div class="code-art-line"><em>01</em> <span>while</span> (learning) {</div><div class="code-art-line"><em>02</em> &nbsp; solve();</div><div class="code-art-line"><em>03</em> &nbsp; understand();</div><div class="code-art-line"><em>04</em> &nbsp; repeat();</div><div class="code-art-line"><em>05</em> }</div><div class="code-art-check">${icon('check',13)} Small steps. Real progress.</div></div></section><section class="daily-pulse"><div class="pulse-ring" style="--pct:${Math.min(100,actual/target*100)}%"><div><b>${actual}</b><span>MIN TODAY</span></div></div><div>${label('TODAY’S FOCUS')}<h3>${target} minute goal</h3><p>${minutes.dsa}m DSA <span>·</span> ${minutes.design}m design</p><a href="#planner">Plan & log your day ${icon('arrow',14)}</a></div></section></div><div class="sheet-body"><section class="sheet-catalog"><div class="catalog-title"><div><h2>The DSA prep sheet <span>A — Z</span></h2><p>Work through patterns, not deadlines.</p></div><a class="review-shortcut" href="#reviews">${icon('repeat',15)} Revision <b>${s.due.length}</b></a></div><div class="sheet-toolbar"><label class="sheet-search">${icon('search',18)}<input id="problem-search" type="search" aria-label="Search problems" placeholder="Find a problem or pattern…" value="${esc(f.query)}"></label><div class="sheet-tracks">${[['Core','Core 96'],['Extended','Extra 60'],['all','All 156']].map(([v,t])=>`<button data-track="${v}" aria-pressed="${f.track===v}" class="${f.track===v?'selected':''}">${t}</button>`).join('')}</div></div><div class="sheet-filters"><label><span>Level</span><select data-filter="difficulty" aria-label="Difficulty">${['all','Easy','Medium','Hard','Varies'].map(v=>`<option value="${v}" ${f.difficulty===v?'selected':''}>${v==='all'?'All levels':v}</option>`).join('')}</select></label><label><span>Status</span><select data-filter="status" aria-label="Problem progress">${['all','Not started','Attempted','Solved with help','Solved independently','Retained'].map(v=>`<option value="${v}" ${f.status===v?'selected':''}>${v==='all'?'Any progress':v}</option>`).join('')}</select></label><span id="result-count">${rows.length} problems</span><button data-action="reset-filters" class="text-button">Reset</button></div><div id="problem-results">${groups(rows)}</div></section><aside class="sheet-rail"><section class="rail-progress">${label('THE BIG PICTURE')}<div class="core-percent">${pct}<span>%</span></div><h3>Understanding takes practice.</h3><div class="rail-bar"><i style="width:${pct}%"></i></div><p>${s.solved} of 96 core problems independently solved. Optional problems never dilute your progress.</p></section><section class="rail-method">${label('YOUR PRACTICE LOOP')}<div><b>01</b><span><strong>Think first</strong><small>Clarify. Try a simple approach.</small></span></div><div><b>02</b><span><strong>Make it work</strong><small>Code, test, explain complexity.</small></span></div><div><b>03</b><span><strong>Make it stick</strong><small>Return and solve independently.</small></span></div></section><section class="rail-note">${icon('java',22)}<h3>Java help, right there.</h3><p>Each problem has a targeted refresher when you need one.</p></section></aside></div>`;}
function planner(){const day=date(),anchor=month||day.slice(0,7)+'-01',base=new Date(anchor+'T12:00:00Z'),offset=(base.getUTCDay()+6)%7,start=addDays(anchor,-offset),plans=latestPlans(state()).sort((a,b)=>a.targetId.localeCompare(b.targetId)),dayPlans=plans.filter(e=>e.date===day&&e.status!=='Skipped'),time=studyMinutes(state(),day),actual=time.dsa+time.design,planned=dayPlans.reduce((n,e)=>n+e.minutes,0),monthTitle=new Intl.DateTimeFormat('en',{month:'long',year:'numeric',timeZone:'UTC'}).format(base),name=new Intl.DateTimeFormat('en',{weekday:'long',day:'numeric',month:'long',timeZone:'UTC'}).format(new Date(day+'T12:00:00Z'));
return `<div class="sheet-heading"><div>${label('A LITTLE STRUCTURE. ROOM TO BREATHE.')}<h1>Make time <span>to learn.</span></h1><p>Choose what to study. Log what you actually did.</p></div><div class="planner-legend"><span><i></i> DSA</span><span><i></i> System design</span></div></div><div class="calendar-layout"><section class="calendar-card"><div class="calendar-top"><h2>${monthTitle}</h2><div><button class="icon-button" data-calendar-move="-1" aria-label="Previous month">‹</button><button class="btn outline" data-calendar-today="true">Today</button><button class="icon-button" data-calendar-move="1" aria-label="Next month">›</button></div></div><div class="calendar-weekdays">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<span>${d}</span>`).join('')}</div><div class="calendar-grid">${Array.from({length:42},(_,i)=>{const d=addDays(start,i),items=plans.filter(p=>p.date===d&&p.status!=='Skipped'),t=studyMinutes(state(),d),total=t.dsa+t.design;return `<button data-calendar-day="${d}" aria-label="${d}, ${items.length} planned, ${total} minutes logged" aria-pressed="${d===day}" class="calendar-day ${d.slice(0,7)!==anchor.slice(0,7)?'outside':''} ${d===ctx.today()?'is-today':''} ${d===day?'selected':''}"><span class="day-number">${Number(d.slice(-2))}</span><div class="calendar-events">${items.slice(0,2).map(p=>`<span class="calendar-chip ${p.targetId.startsWith('SD')?'design':'dsa'} ${p.status==='Done'?'done':''}">${p.status==='Done'?'✓ ':''}${esc(topic(p.targetId))}</span>`).join('')}${items.length>2?`<small>+${items.length-2} more</small>`:''}</div>${total?`<span class="calendar-time">${total}m learned</span>`:''}</button>`}).join('')}</div><div class="calendar-caption"><p>Click a date to plan its topics. Completion marks are separate from recorded study time.</p><button class="btn outline" data-auto-plan="true">Plan next 7 days ${icon("spark",15)}</button><small>Uses your daily goal; existing days stay as you planned them.</small></div></section><aside class="day-agenda"><div class="agenda-heading">${label(day===ctx.today()?'TODAY’S AGENDA':'SELECTED DAY')}<h2>${name}</h2><div class="agenda-totals"><div><b>${planned}<small>m</small></b><span>planned</span></div><div><b>${actual}<small>m</small></b><span>logged</span></div></div><p class="time-breakdown">${time.dsa}m DSA <span>·</span> ${time.design}m system design</p></div><div class="day-plan-list">${dayPlans.map(p=>`<article class="day-plan ${p.status==='Done'?'done':''}"><div><span class="eyebrow">${p.targetId.startsWith('SD')?'SYSTEM DESIGN':'JAVA DSA'} · ${p.minutes} MIN</span><h3>${esc(topic(p.targetId))}</h3>${p.notes?`<p>${esc(p.notes)}</p>`:''}</div><div class="day-plan-actions"><button class="text-link" ${p.targetId.startsWith('SD')?`data-design-week="${seed.roadmap.find(w=>w.systemDesignId===p.targetId).week}"`:`data-task="${p.targetId}"`}>Open ${icon('arrow',14)}</button><button class="text-button" data-plan-status="${p.status==='Done'?'Planned':'Done'}" data-plan-id="${p.itemId}">${p.status==='Done'?'Undo done':'Mark done'}</button><button class="icon-button" data-plan-status="Skipped" data-plan-id="${p.itemId}" aria-label="Remove ${esc(topic(p.targetId))} from plan">${icon('close',14)}</button></div></article>`).join('')||'<div class="agenda-empty">A little space for progress.<p>Add one problem or design topic below.</p></div>'}</div><details class="planner-form-panel" open><summary>${icon('plus',17)} Plan a topic</summary><form id="study-plan-form"><input type="hidden" name="date" value="${day}"><label>What will you study?<select name="targetId"><optgroup label="Java DSA">${seed.problems.map(p=>`<option value="${p.id}">${esc(p.title)} · ${p.id}</option>`).join('')}</optgroup><optgroup label="System design">${seed.roadmap.map(w=>`<option value="${w.systemDesignId}">${esc(w.systemDesign)}</option>`).join('')}</optgroup></select></label><label>Planned minutes<input name="minutes" type="number" min="1" max="1440" value="45" required></label><label>Focus note <small>optional</small><input name="notes" placeholder="e.g. Explain time complexity aloud"></label><p class="form-error" role="alert"></p><button class="btn primary" type="submit">Add to this day ${icon('plus',16)}</button></form></details><details class="planner-form-panel"><summary>${icon('clock',17)} Log study time</summary><form id="study-session-form"><input type="hidden" name="date" value="${day}"><p>Only add time you have not already logged with a problem or design session.</p><label>Track<select name="track"><option>DSA</option><option>System design</option></select></label><label>Minutes actually studied<input name="minutes" type="number" min="1" max="1440" value="30" required></label><label>What did you learn?<textarea name="notes" rows="3" required></textarea></label><p class="form-error" role="alert"></p><button class="btn primary" type="submit">Save study time</button></form></details><div class="session-mini"><h3>Time logged on this date</h3>${[...state().attempts.map(e=>({...e,date:e.localDate,title:topic(e.problemId)})),...state().systemDesignEntries.map(e=>({...e,date:e.localDate,title:topic(e.systemDesignId)})),...state().javaRevisionEntries.map(e=>({...e,date:e.localDate,title:'Java refresher'})),...(state().studyEntries||[]).filter(e=>e.kind==='session').map(e=>({...e,title:e.track}))].filter(e=>e.date===day).map(e=>`<div><span>${esc(e.title)}</span><b>${e.minutes||0}m</b></div>`).join('')||'<p>No study time logged yet.</p>'}</div></aside></div>`;}
async function submit(form){const f=new FormData(form),v=n=>String(f.get(n)||'').trim(),id=crypto.randomUUID(),kind=form.id==='study-plan-form'?'plan':'session',e={id,itemId:id,kind,date:v('date'),occurredAt:new Date().toISOString(),minutes:Number(v('minutes')),notes:v('notes')};if(kind==='plan'){e.targetId=v('targetId');e.status='Planned';}else{e.track=v('track');if(!e.notes)throw Error('Add a short learning note.');if(e.date>ctx.today())throw Error('Log actual study time for today or a past date.');}validateStudyEntries([e],seed);await ctx.commit(s=>s.studyEntries.push(e));ctx.saved();ctx.toast(kind==='plan'?'Topic added to your day.':'Study time saved.');}
async function autoPlan(){if(date()<ctx.today())throw Error('Choose today or a future date to generate a plan.');const existing=latestPlans(state()).filter(p=>p.status!=='Skipped'),scheduled=new Set(existing.map(p=>p.targetId)),problems=sum().core.filter(p=>!sum().reviews[p.id].everSolved&&!scheduled.has(p.id)),designs=seed.roadmap.filter(w=>!scheduled.has(w.systemDesignId)&&!state().systemDesignEntries.some(e=>e.systemDesignId===w.systemDesignId&&e.status==='Reviewed')),budget=state().careerProfile.dailyMinutes,days=state().careerProfile.daysPerWeek,records=[];for(let i=0;i<days;i++){const d=addDays(date(),i);if(existing.some(p=>p.date===d))continue;const problem=problems.shift(),design=designs.shift();for(const [targetId,minutes] of [[problem?.id,design?Math.round(budget*.75):budget],[design?.systemDesignId,problem?budget-Math.round(budget*.75):budget]]){if(!targetId)continue;const id=crypto.randomUUID();records.push({id,itemId:id,kind:'plan',date:d,occurredAt:new Date().toISOString(),targetId,minutes,status:'Planned',notes:targetId.startsWith('SD')?'Read the concept, sketch a flow and explain one tradeoff.':'Understand, solve in Java, test edge cases, then revisit a weak pattern.'});}}if(!records.length){ctx.toast('These days already have plans, or the available topics are complete.');return;}validateStudyEntries(records,seed);await ctx.commit(s=>s.studyEntries.push(...records));ctx.refresh();ctx.toast('Your next study days are planned. Change any topic by removing it and adding another.');}
async function click(el){if(el.dataset.autoPlan){if(ctx.discard())await autoPlan();return true;}if(el.dataset.calendarDay){if(!ctx.discard())return true;selected=el.dataset.calendarDay;ctx.refresh();return true;}if(el.dataset.calendarMove||el.dataset.calendarToday){if(!ctx.discard())return true;if(el.dataset.calendarToday){selected=ctx.today();month=selected.slice(0,7)+'-01';}else{const d=new Date((month||date().slice(0,7)+'-01')+'T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+Number(el.dataset.calendarMove));month=d.toISOString().slice(0,10);selected=month;}ctx.refresh();return true;}if(el.dataset.planStatus){if(!ctx.discard())return true;const prior=latestPlans(state()).find(p=>p.itemId===el.dataset.planId);if(!prior)return true;if(el.dataset.planStatus==='Done'&&prior.date>ctx.today())throw Error('Mark completed study on today or a past date.');const e={...prior,id:crypto.randomUUID(),occurredAt:new Date().toISOString(),status:el.dataset.planStatus};validateStudyEntries([e],seed);await ctx.commit(s=>s.studyEntries.push(e));ctx.refresh();ctx.toast('Plan updated.');return true;}return false;}
return {shell,sheet,groups,planner,submit,click};
}
